-- Run explicitly after deploying the image assets. This is demo inventory, not a general migration.
begin;
do $seed$
declare
  target uuid;
  branch uuid;
  item jsonb;
  cover text;
  gallery jsonb;
  style_id_new uuid;
  variant_id_new uuid;
  size_name text;
  group_id uuid;
begin
  select t.id into strict target
  from tenants t join sty_settings s on s.tenant_id = t.id
  where t.slug = 'demo' and lower(btrim(s.shop_name)) = 'genx cloths';
  perform pg_advisory_xact_lock(hashtextextended('genx-studio:' || target, 0));
  select id into strict branch from sty_branches
  where tenant_id = target and is_main and active;
  for item in select value from jsonb_array_elements('[{"category":"T-shirts","name":"Afterimage Graphic Tee","slug":"afterimage-graphic-tee","description":"Washed black heavyweight cotton tee with an electric cobalt chrome-ring and acid-lime comet screenprint.","price":1599,"weightG":270,"fabric":"Heavyweight cotton jersey","sizes":["S","M","L","XL"],"collection":"Offbeat Streetwear","washcare":"Cold wash inside out. Hang dry and avoid ironing the print.","colour":"Washed Black","stock":6,"sku":"GX-ST-001","files":["afterimage-graphic-tee-cover.jpg","afterimage-graphic-tee-angle.jpg","afterimage-graphic-tee-detail.jpg"]},{"category":"T-shirts","name":"Kinetic Bloom Tee","slug":"kinetic-bloom-tee","description":"Bone-white oversized cotton tee with bold cobalt iris and black halftone leaves.","price":1699,"weightG":270,"fabric":"Heavyweight cotton jersey","sizes":["S","M","L","XL"],"collection":"Offbeat Streetwear","washcare":"Cold wash inside out. Hang dry and avoid ironing the print.","colour":"Bone White","stock":7,"sku":"GX-ST-002","files":["kinetic-bloom-tee-cover.jpg","kinetic-bloom-tee-angle.jpg","kinetic-bloom-tee-detail.jpg"]},{"category":"T-shirts","name":"Signal Drift Tee","slug":"signal-drift-tee","description":"Deep burgundy oversized cotton tee with cream and silver abstract racing signal print.","price":1799,"weightG":270,"fabric":"Heavyweight cotton jersey","sizes":["S","M","L","XL"],"collection":"Offbeat Streetwear","washcare":"Cold wash inside out. Hang dry and avoid ironing the print.","colour":"Burgundy","stock":8,"sku":"GX-ST-003","files":["signal-drift-tee-cover.jpg","signal-drift-tee-angle.jpg","signal-drift-tee-detail.jpg"]},{"category":"Shirts","name":"Gridline Camp Shirt","slug":"gridline-camp-shirt","description":"Charcoal short-sleeve camp collar shirt with cobalt architectural grid print.","price":2399,"weightG":390,"fabric":"Woven cotton","sizes":["S","M","L","XL"],"collection":"Field Notes","washcare":"Cold gentle wash. Hang dry.","colour":"Charcoal","stock":9,"sku":"GX-ST-004","files":["gridline-camp-shirt-cover.jpg","gridline-camp-shirt-angle.jpg","gridline-camp-shirt-detail.jpg"]},{"category":"Shirts","name":"Night Current Shirt","slug":"night-current-shirt","description":"Ink blue relaxed button-up with an ivory wave jacquard.","price":2499,"weightG":390,"fabric":"Woven cotton","sizes":["S","M","L","XL"],"collection":"Field Notes","washcare":"Cold gentle wash. Hang dry.","colour":"Ink Blue","stock":6,"sku":"GX-ST-005","files":["night-current-shirt-cover.jpg","night-current-shirt-angle.jpg","night-current-shirt-detail.jpg"]},{"category":"Shirts","name":"Rivet Workshop Shirt","slug":"rivet-workshop-shirt","description":"Warm sand cotton overshirt with rust geometric embroidered patch pockets.","price":2599,"weightG":390,"fabric":"Woven cotton","sizes":["S","M","L","XL"],"collection":"Field Notes","washcare":"Cold gentle wash. Hang dry.","colour":"Sand","stock":7,"sku":"GX-ST-006","files":["rivet-workshop-shirt-cover.jpg","rivet-workshop-shirt-angle.jpg","rivet-workshop-shirt-detail.jpg"]},{"category":"Jeans","name":"Arc Panel Jeans","slug":"arc-panel-jeans","description":"Washed indigo wide-leg jeans with curved contrasting panel seams.","price":2999,"weightG":690,"fabric":"Rigid cotton denim","sizes":["28","30","32","34","36"],"collection":"Denim in Motion","washcare":"Wash cold with similar colours. Hang dry.","colour":"Washed Indigo","stock":8,"sku":"GX-ST-007","files":["arc-panel-jeans-cover.jpg","arc-panel-jeans-angle.jpg","arc-panel-jeans-detail.jpg"]},{"category":"Jeans","name":"Static Carpenter Jeans","slug":"static-carpenter-jeans","description":"Washed black carpenter jeans with gray contrast stitch work.","price":3099,"weightG":690,"fabric":"Rigid cotton denim","sizes":["28","30","32","34","36"],"collection":"Denim in Motion","washcare":"Wash cold with similar colours. Hang dry.","colour":"Washed Black","stock":9,"sku":"GX-ST-008","files":["static-carpenter-jeans-cover.jpg","static-carpenter-jeans-angle.jpg","static-carpenter-jeans-detail.jpg"]},{"category":"Jeans","name":"Chalk Rail Jeans","slug":"chalk-rail-jeans","description":"Ecru straight jeans with offset rust bartacks and graphite topstitching.","price":3199,"weightG":690,"fabric":"Rigid cotton denim","sizes":["28","30","32","34","36"],"collection":"Denim in Motion","washcare":"Wash cold with similar colours. Hang dry.","colour":"Ecru","stock":6,"sku":"GX-ST-009","files":["chalk-rail-jeans-cover.jpg","chalk-rail-jeans-angle.jpg","chalk-rail-jeans-detail.jpg"]},{"category":"Footwear","name":"Transit Court Sneakers","slug":"transit-court-sneakers","description":"Off-white leather low sneakers with cobalt wave panels and charcoal rubber sole.","price":2899,"weightG":720,"fabric":"Leather upper and rubber outsole","sizes":["6","7","8","9","10"],"collection":"","washcare":"Wipe with a damp cloth and air dry.","colour":"Off White","stock":7,"sku":"GX-ST-010","files":["transit-court-sneakers-cover.jpg","transit-court-sneakers-angle.jpg","transit-court-sneakers-detail.jpg"]},{"category":"Footwear","name":"Faultline Runners","slug":"faultline-runners","description":"Charcoal mesh runners with cool silver molded overlays and acid lime details.","price":2999,"weightG":720,"fabric":"Textile and rubber","sizes":["6","7","8","9","10"],"collection":"","washcare":"Wipe with a damp cloth and air dry.","colour":"Charcoal","stock":8,"sku":"GX-ST-011","files":["faultline-runners-cover.jpg","faultline-runners-angle.jpg","faultline-runners-detail.jpg"]},{"category":"Footwear","name":"Dune Trail Sandals","slug":"dune-trail-sandals","description":"Sand webbing outdoor sandals with charcoal wave footbed and cobalt tabs.","price":3099,"weightG":720,"fabric":"Textile and rubber","sizes":["6","7","8","9","10"],"collection":"","washcare":"Wipe with a damp cloth and air dry.","colour":"Sand","stock":9,"sku":"GX-ST-012","files":["dune-trail-sandals-cover.jpg","dune-trail-sandals-angle.jpg","dune-trail-sandals-detail.jpg"]},{"category":"Bags","name":"Contour Sling","slug":"contour-sling","description":"Charcoal woven crescent bag with cobalt topographic stitch and black webbing.","price":2299,"weightG":420,"fabric":"Woven fabric with webbing","sizes":["One size"],"collection":"Urban Carry","washcare":"Spot clean with a damp cloth. Air dry.","colour":"Charcoal","stock":6,"sku":"GX-ST-013","files":["contour-sling-cover.jpg","contour-sling-angle.jpg","contour-sling-detail.jpg"]},{"category":"Bags","name":"Relay Tote","slug":"relay-tote","description":"Bone canvas utility tote with navy panels and racing red woven strap.","price":2399,"weightG":420,"fabric":"Woven fabric with webbing","sizes":["One size"],"collection":"Urban Carry","washcare":"Spot clean with a damp cloth. Air dry.","colour":"Bone White","stock":7,"sku":"GX-ST-014","files":["relay-tote-cover.jpg","relay-tote-angle.jpg","relay-tote-detail.jpg"]},{"category":"Bags","name":"Switchyard Backpack","slug":"switchyard-backpack","description":"Ink-blue ripstop daypack with black front panel and thin silver bungee.","price":2499,"weightG":420,"fabric":"Woven fabric with webbing","sizes":["One size"],"collection":"Urban Carry","washcare":"Spot clean with a damp cloth. Air dry.","colour":"Ink Blue","stock":8,"sku":"GX-ST-015","files":["switchyard-backpack-cover.jpg","switchyard-backpack-angle.jpg","switchyard-backpack-detail.jpg"]},{"category":"Jackets","name":"Static Shell Jacket","slug":"static-shell-jacket","description":"Black technical zip shell with cobalt rippling panel artwork.","price":3499,"weightG":620,"fabric":"Woven shell","sizes":["S","M","L","XL"],"collection":"Field Notes","washcare":"Cold gentle wash with closures fastened. Hang dry.","colour":"Black","stock":9,"sku":"GX-ST-016","files":["static-shell-jacket-cover.jpg","static-shell-jacket-angle.jpg","static-shell-jacket-detail.jpg"]},{"category":"Jackets","name":"Afterglow Coach Jacket","slug":"afterglow-coach-jacket","description":"Burgundy coach jacket with cream geometric back print.","price":3599,"weightG":620,"fabric":"Woven shell","sizes":["S","M","L","XL"],"collection":"Field Notes","washcare":"Cold gentle wash with closures fastened. Hang dry.","colour":"Burgundy","stock":6,"sku":"GX-ST-017","files":["afterglow-coach-jacket-cover.jpg","afterglow-coach-jacket-angle.jpg","afterglow-coach-jacket-detail.jpg"]},{"category":"Jackets","name":"Quarry Work Jacket","slug":"quarry-work-jacket","description":"Washed sand canvas cropped work jacket with charcoal patches.","price":3699,"weightG":620,"fabric":"Woven shell","sizes":["S","M","L","XL"],"collection":"Field Notes","washcare":"Cold gentle wash with closures fastened. Hang dry.","colour":"Sand","stock":7,"sku":"GX-ST-018","files":["quarry-work-jacket-cover.jpg","quarry-work-jacket-angle.jpg","quarry-work-jacket-detail.jpg"]},{"category":"Accessories","name":"Signal Beanie","slug":"signal-beanie","description":"Charcoal ribbed beanie with cobalt abstract embroidered badge.","price":999,"weightG":110,"fabric":"Rib knit","sizes":["One size"],"collection":"Small Essentials","washcare":"Spot clean and air dry.","colour":"Charcoal","stock":8,"sku":"GX-ST-019","files":["signal-beanie-cover.jpg","signal-beanie-angle.jpg","signal-beanie-detail.jpg"]},{"category":"Accessories","name":"Gridline Cap","slug":"gridline-cap","description":"Navy six-panel cap with cream graphic grid embroidery.","price":1099,"weightG":110,"fabric":"Mixed materials","sizes":["One size"],"collection":"Small Essentials","washcare":"Spot clean and air dry.","colour":"Navy","stock":9,"sku":"GX-ST-020","files":["gridline-cap-cover.jpg","gridline-cap-angle.jpg","gridline-cap-detail.jpg"]},{"category":"Accessories","name":"Rail Card Wallet","slug":"rail-card-wallet","description":"Black pebbled leather card wallet with burgundy inlaid angular stripe.","price":1199,"weightG":110,"fabric":"Pebbled leather","sizes":["One size"],"collection":"Small Essentials","washcare":"Spot clean and air dry.","colour":"Black","stock":6,"sku":"GX-ST-021","files":["rail-card-wallet-cover.jpg","rail-card-wallet-angle.jpg","rail-card-wallet-detail.jpg"]},{"category":"Phone Cases","name":"Flux Grip Case","slug":"flux-grip-case","description":"Charcoal protective smartphone case with raised cobalt wave ridges.","price":1199,"weightG":40,"fabric":"TPU bumper and rigid back","sizes":["iPhone 16"],"collection":"Small Essentials","washcare":"Remove from the phone and wipe with a soft damp cloth.","colour":"Charcoal","stock":7,"sku":"GX-ST-022","files":["flux-grip-case-cover.jpg","flux-grip-case-angle.jpg","flux-grip-case-detail.jpg"]},{"category":"Phone Cases","name":"Contour Shell Case","slug":"contour-shell-case","description":"Bone smartphone case with graphite topographic print.","price":1299,"weightG":40,"fabric":"TPU bumper and rigid back","sizes":["iPhone 16"],"collection":"Small Essentials","washcare":"Remove from the phone and wipe with a soft damp cloth.","colour":"Bone White","stock":8,"sku":"GX-ST-023","files":["contour-shell-case-cover.jpg","contour-shell-case-angle.jpg","contour-shell-case-detail.jpg"]},{"category":"Phone Cases","name":"Ember Signal Case","slug":"ember-signal-case","description":"Burgundy smartphone case with high contrast cream halftone rings.","price":1399,"weightG":40,"fabric":"TPU bumper and rigid back","sizes":["iPhone 16"],"collection":"Small Essentials","washcare":"Remove from the phone and wipe with a soft damp cloth.","colour":"Burgundy","stock":9,"sku":"GX-ST-024","files":["ember-signal-case-cover.jpg","ember-signal-case-angle.jpg","ember-signal-case-detail.jpg"]}]'::jsonb) loop
    if exists (select 1 from sty_styles where tenant_id = target and code = item->>'sku') then continue; end if;
    cover := '/store/genx-studio/' || (item->'files'->>0);
    select jsonb_agg('/store/genx-studio/' || f.name order by f.position)
      into gallery from jsonb_array_elements_text(item->'files') with ordinality f(name, position) where f.position > 1;
    insert into sty_styles (tenant_id, name, category, brand, code, description, details, fabric, washcare, weight_g, photo_url, photos, price, mrp, collection)
      values (target, item->>'name', item->>'category', 'GenX Cloths', item->>'sku', item->>'description',
        concat_ws(E'\n', item->>'fabric', item->>'colour'), item->>'fabric', item->>'washcare', (item->>'weightG')::int,
        cover, gallery, (item->>'price')::numeric, (item->>'price')::numeric, nullif(item->>'collection', ''))
      returning id into style_id_new;
    for size_name in select jsonb_array_elements_text(item->'sizes') loop
      insert into sty_variants (tenant_id, style_id, colour, size, barcode, sku)
        values (target, style_id_new, item->>'colour', size_name,
          (item->>'sku') || '-' || replace(upper(size_name), ' ', '-'), (item->>'sku') || '-' || replace(upper(size_name), ' ', '-'))
        returning id into variant_id_new;
      insert into sty_stock_moves (tenant_id, branch_id, variant_id, qty, kind, note)
        values (target, branch, variant_id_new, (item->>'stock')::int, 'opening', 'GenX studio demo catalogue');
    end loop;
    if item->>'collection' <> '' then
      select id into group_id from sty_collections where tenant_id = target and lower(name) = lower(item->>'collection');
      if group_id is not null then
        insert into sty_collection_styles (collection_id, style_id, tenant_id) values (group_id, style_id_new, target);
      end if;
    end if;
  end loop;
end $seed$;
commit;
